$("#chat-thread").addEventListener("click",async e=>{const b=e.target.closest("[data-delete-chat-message]");if(!b||!confirm("¿Eliminar este mensaje del chat?"))return;const r=await client.from("messages").delete().eq("id",b.dataset.deleteChatMessage);if(r.error){notice("No se pudo moderar el mensaje: "+r.error.message,true);return}notice("Mensaje eliminado.");await openConversation(activeConversation);await loadMessages()});
$("#chat-reply-form").addEventListener("submit",async e=>{e.preventDefault();if(!activeConversation)return;const body=$("#chat-reply").value.trim();if(!body)return;const btn=$("#chat-send");btn.disabled=true;try{const r=await client.from("messages").insert({conversation_id:activeConversation,sender_id:user.id,body});if(r.error)throw r.error;$("#chat-reply").value="";await openConversation(activeConversation);await loadMessages();notice("Mensaje enviado al chat.")}catch(err){notice("No se pudo enviar: "+err.message,true)}finally{btn.disabled=false}});
async function sendDirectChatMessage(targetId,body,notify=true){
 if(!user?.id||user.app_metadata?.role!=="admin")throw new Error("No tienes permisos administrativos.");
 const [cr,mr]=await Promise.all([client.from("conversations").select("id,created_by,direct_user_id,group_id").is("group_id",null).limit(500),client.from("conversation_members").select("conversation_id,user_id").in("user_id",[user.id,targetId])]);if(cr.error)throw cr.error;if(mr.error)throw mr.error;
 const memberMap=new Map();(mr.data||[]).forEach(m=>{if(!memberMap.has(m.conversation_id))memberMap.set(m.conversation_id,new Set());memberMap.get(m.conversation_id).add(m.user_id)});
 let cv=(cr.data||[]).find(x=>memberMap.get(x.id)?.has(user.id)&&memberMap.get(x.id)?.has(targetId));
 if(!cv){const made=await client.from("conversations").insert({created_by:user.id,direct_user_id:targetId,title:null,group_id:null}).select("id").single();if(made.error)throw made.error;cv={id:made.data.id};const added=await client.from("conversation_members").upsert([{conversation_id:cv.id,user_id:user.id},{conversation_id:cv.id,user_id:targetId}],{onConflict:"conversation_id,user_id"});if(added.error)throw added.error}
 const sent=await client.from("messages").insert({conversation_id:cv.id,sender_id:user.id,body});if(sent.error)throw sent.error;if(notify)await sendAdminNotification(targetId,"Nuevo mensaje de JOA",body.slice(0,300),"admin_message",{conversation_id:cv.id});return cv.id;
}
let rewardSelectedCatalogItems=[],rewardCustomItems=[],rewardEditingItemIndex=-1,rewardCampaignRows=[];
function readAdminRewardBundle(details){const raw=String(details||""),prefix=["JOA_REWARD_BUNDLE_V2::","JOA_REWARD_BUNDLE_V1::"].find(x=>raw.startsWith(x));if(!prefix)return{text:raw,products:[],items:[]};try{const d=JSON.parse(raw.slice(prefix.length));return{text:String(d.text||""),products:Array.isArray(d.products)?d.products.slice(0,12):[],items:Array.isArray(d.items)?d.items.slice(0,40):[]}}catch(e){return{text:raw,products:[],items:[]}}}
function writeAdminRewardBundle(t,products,items){const clean=(products||[]).slice(0,12).map(p=>({key:String(p.key||"").slice(0,180),title:String(p.title||"Producto").slice(0,180),image_url:String(p.image_url||"").slice(0,2000),type:String(p.type||"").slice(0,80),year:String(p.year||"").slice(0,30),description:String(p.description||"").slice(0,500),facts:Array.isArray(p.facts)?p.facts.slice(0,10):[]})),extras=(items||[]).slice(0,40).map(x=>({id:String(x.id||"").slice(0,80),kind:String(x.kind||"custom"),title:String(x.title||"Elemento").slice(0,180),category:String(x.category||"").slice(0,100),quantity:Math.max(1,Math.min(999,Number(x.quantity)||1)),value:String(x.value||"").slice(0,80),discount:String(x.discount||"").slice(0,80),image_url:String(x.image_url||"").slice(0,2000),access:String(x.access||"").slice(0,1000),description:String(x.description||"").slice(0,1500),conditions:String(x.conditions||"").slice(0,1200)}));return clean.length||extras.length?"JOA_REWARD_BUNDLE_V2::"+JSON.stringify({text:String(t||"").slice(0,1800),products:clean,items:extras}):String(t||"").trim()}
function adminCatalogProduct(x){const title=String(x.title||x.name||x.nombre||x.titulo||x.game||x.game_name||x.movie_name||"Contenido JOA"),type=String(x.type||x.tipo||x.category||x.categoria||"Contenido"),image_url=String(x.image_url||x.cover_url||x.cover||x.poster||x.poster_url||x.caratula||x.thumbnail||x.img||x.image||""),year=String(x.year||x.release_year||x.ano||x.año||""),description=String(x.synopsis||x.sinopsis||x.description||x.descripcion||x.overview||x.summary||x.resumen||"").slice(0,500),key=String(x.id??x.external_id??x.igdb_id??x.tmdb_id??x.slug??title).slice(0,180);return{key,title,image_url,type,year,description,facts:[]}}
function rewardMatches(x){const q=($("#reward-catalog-search").value||"").trim().toLocaleLowerCase("es"),cat=$("#reward-catalog-category").value,p=adminCatalogProduct(x),raw=p.type.toLocaleLowerCase("es"),aliases={juego:["juego","game"],pelicula:["pelicula","película","movie","film"],serie:["serie","series","tv"],anime:["anime"],novela:["novela","telenovela"],software:["software","programa","app"],musica:["musica","música","audio"],otros:["otro","otros"]};return(!cat||(aliases[cat]||[cat]).some(v=>raw.includes(v)))&&(!q||[p.title,p.type,p.description,p.year].join(" ").toLocaleLowerCase("es").includes(q))}
function renderRewardItems(){const h=$("#reward-items-list");h.innerHTML="";$("#reward-items-count").textContent=rewardCustomItems.length+" elemento(s)";if(!rewardCustomItems.length){h.innerHTML='<div class="empty">Añade los componentes que formarán parte de este paquete.</div>';return}rewardCustomItems.forEach((x,i)=>{const row=document.createElement("article");row.className="reward-custom-item";const copy=document.createElement("div"),title=document.createElement("b"),meta=document.createElement("small"),desc=document.createElement("p"),actions=document.createElement("div"),edit=document.createElement("button"),del=document.createElement("button");title.textContent=(x.quantity>1?x.quantity+" × ":"")+x.title;meta.textContent=[x.kind,x.category,x.value,x.discount].filter(Boolean).join(" · ");desc.textContent=[x.description,x.conditions].filter(Boolean).join(" | ");copy.append(title,meta);if(desc.textContent)copy.append(desc);edit.type=del.type="button";edit.className=del.className="secondary";edit.textContent="Editar";del.textContent="Quitar";edit.addEventListener("click",()=>{const f={"reward-item-kind":x.kind,"reward-item-title":x.title,"reward-item-category":x.category,"reward-item-quantity":x.quantity,"reward-item-value":x.value,"reward-item-discount":x.discount,"reward-item-image":x.image_url,"reward-item-access":x.access,"reward-item-description":x.description,"reward-item-conditions":x.conditions};Object.entries(f).forEach(([id,v])=>$("#"+id).value=v??"");rewardEditingItemIndex=i;$("#reward-item-add").textContent="Guardar cambios del elemento"});del.addEventListener("click",()=>{rewardCustomItems.splice(i,1);rewardEditingItemIndex=-1;renderRewardItems()});actions.append(edit,del);row.append(copy,actions);h.append(row)})}
function addRewardItem(){const v=id=>$("#"+id).value.trim(),title=v("reward-item-title");if(!title){notice("Escribe el nombre del elemento.",true);return}if(rewardEditingItemIndex<0&&rewardCustomItems.length>=40){notice("El paquete admite hasta 40 elementos personalizados.",true);return}const x={id:rewardEditingItemIndex>=0?rewardCustomItems[rewardEditingItemIndex].id:"item-"+Date.now(),kind:v("reward-item-kind")||"custom",title,category:v("reward-item-category"),quantity:Math.max(1,Math.min(999,Number(v("reward-item-quantity"))||1)),value:v("reward-item-value"),discount:v("reward-item-discount"),image_url:v("reward-item-image"),access:v("reward-item-access"),description:v("reward-item-description"),conditions:v("reward-item-conditions")};if(rewardEditingItemIndex>=0)rewardCustomItems[rewardEditingItemIndex]=x;else rewardCustomItems.push(x);rewardEditingItemIndex=-1;["reward-item-title","reward-item-category","reward-item-value","reward-item-discount","reward-item-image","reward-item-access","reward-item-description","reward-item-conditions"].forEach(id=>$("#"+id).value="");$("#reward-item-kind").value="custom";$("#reward-item-quantity").value="1";$("#reward-item-add").textContent="＋ Añadir elemento al paquete";renderRewardItems()}
function renderRewardProducts(){const h=$("#reward-product-preview");h.innerHTML="";h.hidden=!rewardSelectedCatalogItems.length;rewardSelectedCatalogItems.forEach((p,i)=>{const row=document.createElement("div"),img=document.createElement("img"),copy=document.createElement("div"),b=document.createElement("b"),small=document.createElement("small"),del=document.createElement("button");img.src=p.image_url||"assets/ioa-multiverso-icon.svg";img.alt="";b.textContent=p.title;small.textContent=[p.type,p.year].filter(Boolean).join(" · ");del.type="button";del.className="secondary";del.textContent="Quitar";del.addEventListener("click",()=>{rewardSelectedCatalogItems.splice(i,1);renderRewardProducts();renderRewardCatalog()});copy.append(b,small);row.append(img,copy,del);h.append(row)});$("#reward-catalog-selected-count").textContent=rewardSelectedCatalogItems.length+" de 12 productos seleccionados"}
function renderRewardCatalog(){const h=$("#reward-catalog-results");h.innerHTML="";const matches=catalog.filter(rewardMatches).slice(0,100);if(!matches.length){h.innerHTML='<div class="empty">No encontramos productos con esos filtros.</div>';return}matches.forEach(x=>{const p=adminCatalogProduct(x),selected=rewardSelectedCatalogItems.some(v=>v.key===p.key),btn=document.createElement("button"),img=document.createElement("img"),info=document.createElement("span"),b=document.createElement("b"),type=document.createElement("small"),desc=document.createElement("small"),act=document.createElement("strong");btn.type="button";btn.className="reward-catalog-result"+(selected?" is-selected":"");img.src=p.image_url||"assets/ioa-multiverso-icon.svg";img.alt="";b.textContent=p.title;type.textContent=p.type+(p.year?" · "+p.year:"");desc.textContent=p.description;act.textContent=selected?"✓ Seleccionado · Quitar":"＋ Añadir";info.append(b,type,desc);btn.append(img,info,act);btn.addEventListener("click",()=>{const i=rewardSelectedCatalogItems.findIndex(v=>v.key===p.key);if(i>=0)rewardSelectedCatalogItems.splice(i,1);else if(rewardSelectedCatalogItems.length>=12){notice("Puedes añadir hasta 12 productos del catálogo.",true);return}else rewardSelectedCatalogItems.push(p);renderRewardProducts();renderRewardCatalog()});h.append(btn)});$("#reward-catalog-apply").disabled=!rewardSelectedCatalogItems.length}
function toggleRewardKind(){const service=$("#reward-kind").value==="service_purchase";$("#reward-service-config").hidden=!service;$("#reward-community-requirements").hidden=service;$("#reward-group-wrap").hidden=service;$("#reward-campaign-product-picker").hidden=service;$("#reward-weekly-config").hidden=service;if(service){rewardSelectedCatalogItems=[];renderRewardProducts();$("#reward-type").value="service";$("#reward-mode").value="manual";$("#reward-winners").value="100";$("#reward-weekly").checked=false}}
