$("#rewards-list").addEventListener("click",async e=>{const edit=e.target.closest("[data-reward-edit]"),status=e.target.closest("[data-reward-status]"),draw=e.target.closest("[data-reward-draw]"),del=e.target.closest("[data-reward-delete]"),claim=e.target.closest("[data-claim-status]");if(edit){const c=rewardCampaignRows.find(x=>x.id===edit.dataset.rewardEdit);if(c)fillRewardForm(c);return}if(status){const r=await client.from("reward_campaigns").update({status:status.dataset.status,updated_at:new Date().toISOString()}).eq("id",status.dataset.rewardStatus);if(r.error){notice(r.error.message,true);return}notice("Estado del paquete actualizado.");await loadRewards();return}if(draw){const c=rewardCampaignRows.find(x=>x.id===draw.dataset.rewardDraw);if(!c||!confirm(c.weekly_enabled?"¿Cerrar la semana y sortear los ganadores? El resultado no podrá repetirse esta semana.":"¿Ejecutar ahora la selección de ganadores?"))return;const r=await client.rpc("draw_reward_winners",{p_campaign_id:c.id});if(r.error){notice(r.error.message,true);return}notice(r.data?.already_drawn?"El sorteo de esta semana ya fue realizado.":"Sorteo completado: "+(r.data?.selected_now||0)+" ganador(es).");await loadRewards();return}if(del){if(!confirm("¿Eliminar este paquete y sus solicitudes asociadas?"))return;const r=await client.from("reward_campaigns").delete().eq("id",del.dataset.rewardDelete);if(r.error){notice(r.error.message,true);return}notice("Paquete eliminado.");await loadRewards();return}if(claim){const x=(cache.claims||[]).find(v=>v.id===claim.dataset.claimStatus);if(!x)return;const note=prompt("Mensaje para el usuario (opcional):","");if(note===null)return;const patch={status:claim.dataset.status,admin_note:note,reviewed_by:user.id,reviewed_at:new Date().toISOString()};if(claim.dataset.status==="delivered")patch.delivered_at=new Date().toISOString();const r=await client.from("reward_claims").update(patch).eq("id",x.id);if(r.error){notice(r.error.message,true);return}try{await sendAdminNotification(x.user_id,"Actualización de tu recompensa",note||"Tu solicitud de "+(x.reward_campaigns?.title||"recompensa")+" ha sido actualizada.","reward",{claim_id:x.id,campaign_id:x.campaign_id})}catch(err){notice("Solicitud actualizada, pero no se pudo enviar el aviso: "+err.message,true);await loadRewards();return}notice("Solicitud actualizada y usuario notificado.");await loadRewards()}});
$("#reward-weekly-admin").addEventListener("click",async e=>{const b=e.target.closest("[data-weekly-draw]");if(!b)return;const c=rewardCampaignRows.find(x=>x.id===b.dataset.weeklyDraw);if(!c||!confirm("¿Realizar el sorteo semanal de "+c.title+"? Esta semana quedará cerrada para nuevos sorteos."))return;b.disabled=true;try{const r=await client.rpc("draw_reward_winners",{p_campaign_id:c.id});if(r.error)throw r.error;notice(r.data?.already_drawn?"El sorteo de esta semana ya estaba realizado.":"Sorteo completado: "+(r.data?.selected_now||0)+" ganador(es).");await loadRewards()}catch(err){notice(err.message,true)}finally{b.disabled=false}});
$("#reward-weekly-winners").addEventListener("click",async e=>{const b=e.target.closest("[data-weekly-winner]");if(!b)return;const w=(cache.weeklyWinners||[]).find(x=>x.id===b.dataset.weeklyWinner);if(!w)return;const next=prompt("Estado de entrega: pending, contacted, delivered o rejected",w.delivery_status);if(!next||!["pending","contacted","delivered","rejected"].includes(next))return;const note=prompt("Nota administrativa (opcional):",w.admin_note||"");if(note===null)return;const patch={delivery_status:next,admin_note:note,delivered_at:next==="delivered"?new Date().toISOString():null};const r=await client.from("reward_winners").update(patch).eq("id",w.id);if(r.error){notice(r.error.message,true);return}if(next==="delivered"&&w.user_id){try{await sendAdminNotification(w.user_id,"Tu premio JOA REWARDS fue entregado",note||"Tu premio semanal ha sido marcado como entregado.","reward",{winner_id:w.id,campaign_id:w.campaign_id})}catch(err){notice("Entrega actualizada; no se pudo enviar la notificación: "+err.message,true)}}notice("Estado de entrega actualizado.");await loadRewards()});
function populateMessageUsers(){const select=$("#message-user");if(!select)return;const old=select.value;select.innerHTML='<option value="">Selecciona un usuario</option>'; (cache.users||[]).forEach(p=>{const o=document.createElement("option");o.value=p.id;o.textContent=(p.display_name||p.username||"Jugador")+" · @"+(p.username||"sin_usuario");select.append(o)});if(old)select.value=old}
$("#users-table").addEventListener("click",async e=>{const edit=e.target.closest("[data-edit-profile]"),msg=e.target.closest("[data-message-user]");if(msg){go("messages");$("#message-user").value=msg.dataset.messageUser;$("#message-body").focus();return}if(!edit)return;const p=(cache.users||[]).find(x=>x.id===edit.dataset.editProfile);if(!p)return;const name=prompt("Nombre público:",p.display_name||"");if(name===null)return;const bio=prompt("Biografía:",p.bio||"");if(bio===null)return;const games=prompt("Preferencias de juegos:",p.game_preferences||"");if(games===null)return;const r=await client.from("profiles").update({display_name:name.trim(),bio:bio.trim(),game_preferences:games.trim(),updated_at:new Date().toISOString()}).eq("id",p.id);if(r.error){notice("No se pudo editar el perfil: "+r.error.message,true);return}notice("Perfil actualizado.");await loadUsers()});
async function sendAdminNotification(userId,title,body,type="admin_message",data={}){if(!user?.id||user.app_metadata?.role!=="admin")throw new Error("No tienes permisos administrativos.");if(!userId)throw new Error("Selecciona un destinatario.");const payload={user_id:userId,type,title,body,data:{...data,source:"admin_panel",sent_by:user.id}};const r=await client.from("notifications").insert(payload).select("id").single();if(r.error)throw r.error;return r.data}
$("#admin-message-form").addEventListener("submit",async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;$("#message-status").textContent="Enviando mensaje…";try{const target=$("#message-user").value,body=$("#message-body").value.trim(),notify=$("#message-notify").value==="true";await sendDirectChatMessage(target,body,notify);notice(notify?"Mensaje enviado y notificación entregada.":"Mensaje enviado al chat.");$("#message-status").textContent="Enviado correctamente.";e.currentTarget.reset();await loadMessages()}catch(err){$("#message-status").textContent=err.message;notice("No se pudo enviar: "+err.message,true)}finally{btn.disabled=false}});
